def reclaim_id(lb,body,close):return f'RECLAIM_L{lb}_B{body:g}_C'+('NONE' if close is None else f'{close:g}')

def rr_id(kind, rr):
    return kind+'__RR'+format(rr,'.2f').replace('.','P')

def study_definitions():
    rows=[]
    for rr in RR_LEVELS:
        for kind in ('PRIMARY','RECLAIM','COMBINED'):
            rows.append({'id':rr_id(kind,rr),'kind':kind,'anchor':'PRIMARY',
                'family':'FROZEN_ENTRY_RR_STABILITY','scope':{'PRIMARY':'PRIMARY','RECLAIM':'RECLAIM_ONLY','COMBINED':'PRIMARY_OR_RECLAIM'}[kind],
                'feature':None,'cap':None,'availability':False,'body':1.40 if kind=='PRIMARY' else 1.50,
                'lookback':40 if kind=='PRIMARY' else 30,'distance':.50 if kind=='PRIMARY' else None,
                'rr':rr,'ratio':.60 if kind=='PRIMARY' else None,'close':None if kind=='PRIMARY' else .90,
                'range':1.50 if kind=='PRIMARY' else 0.,'regional':False})
    require(len(rows)==9 and len({d['id'] for d in rows})==9,'Pass14 stream count')
