DEFINITIONS=study_definitions()
DEFINITION_BY_ID={d['id']:d for d in DEFINITIONS}

def configs():return [(d['id'],d['family'],d['lookback'],d['distance'],d['body'],d['range']) for d in DEFINITIONS]

def anchor_for(cid):
    return next(a for a in FROZEN_ENTRIES if a[0]==DEFINITION_BY_ID[cid]['anchor'])

def anchor_qualifies(f,anchor):
    _,_,l,d,b,r=anchor
    return f['distances'][l]<=d and f['body_atr']>=b and f['range_atr']>=r

def comparator_qualifies(f,comparator):return f.get('exact_engulf',True) and anchor_qualifies(f,comparator) and f['body_ratio']>=.60

def condition_passes(f,d):
    if d['feature'] is None:return True
    v=f[d['feature']]
    return v is not None and (d['availability'] or v<=d['cap'])

def condition_metadata(cid,raw):
    d=DEFINITION_BY_ID[cid]
    return {'anchor':d['anchor'],'conditions_json':json.dumps({'kind':d['kind'],'reclaim_lookback':d['lookback'] if d['kind'] in ('RECLAIM','COMBINED') else None,'body_atr_floor':d['body'],'close_location_floor':d['close'],'strict_low_sweep_and_close_reclaim':d['kind'] in ('RECLAIM','COMBINED'),'primary_bypasses_reclaim':d['kind']=='COMBINED'},sort_keys=True),
            'h4_vol_cap':1.10 if d['kind']=='VOL_COMPARATOR' else None,'daily_vol_cap':None,'condition_scope':d['scope'],'availability_only':False,'body_ratio_floor':d['ratio'],'missing_feature_signals':0,'reward_risk':d['rr'],'signal_close_floor':d['close'],'stream_kind':d['kind']}

def study_boundaries(cid):
    rr=DEFINITION_BY_ID[cid]['rr']
    labels=['RR_LOWER_BOUND' if rr==RR_LEVELS[0] else ('RR_UPPER_BOUND' if rr==RR_LEVELS[-1] else 'RR_INTERIOR')]
    if rr==STUDY_RR:labels.append('FROZEN_RR_REFERENCE')
    if rr==NOMINATED_RR:labels.append('RR250_CONTROL')
    if rr==CANDIDATE_RR:labels.append('FROZEN_CONFIRMATION_CANDIDATE')
    return ','.join(labels)


def comparison_pairs():
    pairs=[]
    for rr in RR_LEVELS:
        pairs.extend([(rr_id('PRIMARY',rr),rr_id('COMBINED',rr),'INCREMENTAL_TO_PRIMARY_SAME_RR'),
                      (rr_id('RECLAIM',rr),rr_id('COMBINED',rr),'CORE_ADDED_TO_RECLAIM_SAME_RR'),
                      (rr_id('PRIMARY',rr),rr_id('RECLAIM',rr),'STANDALONE_VS_PRIMARY_SAME_RR')])
    for kind in ('PRIMARY','RECLAIM','COMBINED'):
        for rr in RR_LEVELS:
            if rr!=STUDY_RR:pairs.append((rr_id(kind,STUDY_RR),rr_id(kind,rr),'VS_FROZEN_RR275_REFERENCE'))
            if rr!=NOMINATED_RR:pairs.append((rr_id(kind,NOMINATED_RR),rr_id(kind,rr),'VS_RR250_CONTROL'))
        for a,b in zip(RR_LEVELS,RR_LEVELS[1:]):pairs.append((rr_id(kind,a),rr_id(kind,b),'ADJACENT_RR'))
    require(len(pairs)==27 and len(set(pairs))==27,'Pass14 comparison count')
    return sorted(pairs)


def condition_neighbours():
    for kind in ('PRIMARY','RECLAIM','COMBINED'):
        for a,b in zip(RR_LEVELS,RR_LEVELS[1:]):
            yield rr_id(kind,a),rr_id(kind,b),'reward_risk'
            yield rr_id(kind,b),rr_id(kind,a),'reward_risk'

def verify_pass13(bars, raw):
    masks,_=independent_mechanism_masks(bars,PASS13_DEFINITIONS)
    union=sorted({i for ids in masks.values() for i in ids})
    paths={rr:{case[0]:{i:path_for(bars,i,case,rr) for i in union} for case in CASES}
           for rr in sorted({d['rr'] for d in PASS13_DEFINITIONS})}
    rows=[]
    for d in PASS13_DEFINITIONS:
        ids=[i for i,f in raw.items() if study_qualifies(f,d)]
        require(ids==masks[d['id']],'Independent archived Pass13 mask mismatch '+d['id'])
        for case in CASES:
            name=case[0];pin=PASS13_PINS[d['id']][name]
            a,r,b=replay(ids,paths[d['rr']][name]);sha=digest([core(v) for v in a])
            rejected=[(v['signal_index'],v['reason']) for v in r]
            blocked=[(v['signal_index'],v['blocking_signal_index']) for v in b]
            require(digest(ids)==pin['raw_signal_hash'] and sha==pin['accepted_hash'],
                    'Pinned Pass13 full-ledger mismatch '+d['id']+' '+name)
            require(digest(rejected)==pin['rejected_hash'] and digest(blocked)==pin['blocked_hash'],
                    'Pinned Pass13 rejected/blocked chronology mismatch')
            require((len(ids),len(a),len(r),len(b))==tuple(int(pin[k]) for k in ('raw_signals','accepted','rejected','blocked')),
                    'Pinned Pass13 counts changed')
            require(abs(sum(v['r'] for v in a if v['r'] is not None)-float(pin['net_r']))<1e-8,
                    'Pinned Pass13 R changed')
            si,aa,rr,bb=independent_stream(bars,case,masks[d['id']],d['rr'])
            require(si==ids and aa==[core(v) for v in a] and rr==rejected and bb==blocked,
                    'Independent archived Pass13 execution mismatch')
            rows.append({'pass13_config':d['id'],'case':name,'reward_risk':d['rr'],
                         'raw_signal_hash':digest(ids),'accepted_hash':sha,
                         'rejected_hash':digest(rejected),'blocked_hash':digest(blocked),
                         'accepted':len(a),'rejected':len(r),'blocked':len(b),'parity':'PASS'})
    require(len(rows)==120,'Incomplete Pass13 archive controls')
    return rows


