def start():
    with START_LOCK:
        if snapshot()['status']=='IDLE':
            update(status='STARTING')
            threading.Thread(target=run,daemon=True).start()


def response(method,path):
    if method not in ('GET','HEAD'):return 405,'application/json',canonical({'error':'Read-only: GET/HEAD only'}),None
    path=urllib.parse.urlsplit(path).path
    if path in ('/','/health','/status'):
        return 200,'application/json',canonical(snapshot()),None
    s=snapshot()['status']
    if path=='/results':
        if s not in ('COMPLETE','ERROR'):return 409,'application/json',canonical({'status':s,'message':'Results not ready; poll /status'}),None
        p=OUTPUT/RESULT_NAME
    elif path=='/source':
        if s!='COMPLETE':return 409,'application/json',canonical({'status':s,'message':'Validated source not ready'}),None
        p=OUTPUT/SOURCE_NAME
    else:return 404,'application/json',canonical({'error':'Use /status, /results or /source'}),None
    if not p.is_file():return 404,'application/json',canonical({'error':'Archive unavailable'}),None
    return 200,'application/zip',None,p


def app(environ,start_response):
    if os.environ.get('EURUSD_H4_PASS15_AUTOSTART',os.environ.get('EURUSD_H4_PASS14_AUTOSTART',os.environ.get('EURUSD_H4_PASS13_AUTOSTART',os.environ.get('EURUSD_H4_PASS12_AUTOSTART',os.environ.get('EURUSD_H4_PASS11_AUTOSTART','true'))))).lower()!='false':start()
    method=environ.get('REQUEST_METHOD','GET');code,mime,body,path=response(method,environ.get('PATH_INFO','/'))
    size=path.stat().st_size if path else len(body)
    headers=[('Content-Type',mime),('Content-Length',str(size)),('Cache-Control','no-store')]
    if path:headers.append(('Content-Disposition','attachment; filename="'+path.name+'"'))
    start_response(str(code)+' '+{200:'OK',404:'Not Found',405:'Method Not Allowed',409:'Conflict'}[code],headers)
    if method=='HEAD':return []
    if not path:return [body]
    def chunks():
        with path.open('rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''):yield chunk
    return chunks()


application=app


class Handler(BaseHTTPRequestHandler):
    def handle_request(self):
        def headers(status,values):
            self.send_response(int(status.split()[0]))
            for k,v in values:self.send_header(k,v)
            self.end_headers()
        try:
            for chunk in app({'REQUEST_METHOD':self.command,'PATH_INFO':self.path},headers):self.wfile.write(chunk)
        except (BrokenPipeError,ConnectionResetError):pass
    do_GET=handle_request
    do_HEAD=handle_request
    do_POST=handle_request
    do_PUT=handle_request
    do_DELETE=handle_request
    def log_message(self,*args):pass


def confirmation_self_test():
    """Exercise the new reconstruction across quote, path and slot boundaries."""
    require(CANDIDATE_RR==2.25 and RR_LEVELS==(2.25,2.50,2.75),'Frozen confirmation RRs')
    require(len(PASS13_DEFINITIONS)==15 and sum(map(len,PASS13_PINS.values()))==120,'Pass13 archive controls missing')
    require(len(CONFIRMATION_REPORT_PINS)==9 and sum(map(len,CONFIRMATION_REPORT_PINS.values()))==72,'Mandatory archived report pins missing')
    def bar(i,o,h,l,c):
        mid=dict(o=o,h=h,l=l,c=c)
        return {'t':START+i*H4,'mid':mid,'bid':dict(mid),'ask':dict(mid,o=o+.00005),
                'first_h1':START+i*H4,'h1_count':4}
    signal=bar(0,1.0995,1.1001,1.099,1.1)
    scenarios=[bar(1,1.1,1.109,1.09,1.101),
               bar(1,1.098,1.10,1.097,1.099),
               bar(1,1.108,1.109,1.107,1.108),
               bar(1,1.1,1.1001,1.0999,1.1)]
    for nextbar in scenarios:
        nextbar['ask']['o']=1.10005
        for case in CASES:
            for rr in RR_LEVELS:
                expected=path_for([signal,nextbar],0,case,rr)
                actual=confirmation_quote_path([signal,nextbar],0,case,rr)
                require(actual==expected,'New confirmation synthetic full-path parity')
    gap=confirmation_quote_path([signal,scenarios[1]],0,CASES[0],CANDIDATE_RR)
    require(gap['r']<-1 and gap['outcome']=='STOP_GAP','Confirmation adverse gap stress')
    cap=confirmation_quote_path([signal,scenarios[2]],0,CASES[0],CANDIDATE_RR)
    require(cap['exit_price']==cap['target'] and cap['outcome']=='TARGET_GAP_CAPPED','Confirmation favourable gap cap')
    aged=bar(1,1.1,1.1001,1.0999,1.1);aged['first_h1']+=121
    require(confirmation_quote_path([signal,aged],0,CASES[-2],CANDIDATE_RR)['reason']=='ENTRY_AGE_EXCEEDS_120S','Confirmation age guard')
    aged['first_h1']-=121;aged['ask']['o']=1.100101
    require(confirmation_quote_path([signal,aged],0,CASES[-2],CANDIDATE_RR)['reason']=='ADVERSE_ENTRY_EXCEEDS_10_TICKS','Confirmation adverse guard')
    require(confirmation_quote_path([signal],0,CASES[-2],CANDIDATE_RR)['reason']=='NO_NEXT_OBSERVED_OPEN','Confirmation missing quote')
    cutoff=dict(signal,t=END-H4)
    require(confirmation_quote_path([cutoff],0,CASES[0],CANDIDATE_RR)['reason']=='SIGNAL_AT_OR_AFTER_CUTOFF','Confirmation cutoff')
    small=bar(0,1.1,1.10002,1.09999,1.1)
    require(confirmation_quote_path([small],0,CASES[4],CANDIDATE_RR)['reason']=='INVALID_ENTRY_STOP_TARGET','Confirmation invalid geometry')
    bars=[signal,bar(1,1.1,1.1026,1.0995,1.102),bar(2,1.102,1.1038,1.101,1.103)]
    audit={i:{'primary':i==0,'reclaim':True} for i in range(3)}
    for case in CASES:
        a,r,b,paths,decisions=confirmation_chronology(bars,[0,1],case,2.25,audit)
        require([v['signal_index'] for v in a]==[0,1] and not b,'Confirmation exit-candle entry')
        a,r,b,paths,decisions=confirmation_chronology(bars,[0,1],case,2.75,audit)
        require([v['signal_index'] for v in a]==[0] and b==[{'signal_index':1,'blocking_signal_index':0}],'Confirmation changed RR occupation')
    empty=confirmation_period([],('EMPTY',START,END,False))
    require(empty['entries']==0 and empty['net_r']==0 and empty['max_closed_r_drawdown']==0,'Confirmation empty periods')
    require(tuple(map(len,confirmation_intervals()))==(31,262,714),'Confirmation independent calendar')


def rr_replay_self_test():
    """Prove changed target duration changes later eligibility, not just payoff."""
    def bar(i,o,h,l,c):
        mid=dict(o=o,h=h,l=l,c=c)
        return {'t':START+i*H4,'mid':mid,'bid':dict(mid),
                'ask':dict(mid,o=o+.00005),'first_h1':START+i*H4,'h1_count':4}
    bars=[bar(0,1.0995,1.1001,1.099,1.1),
          bar(1,1.1,1.1026,1.0995,1.102),
          bar(2,1.102,1.1038,1.101,1.103)]
    for case in CASES:
        accepted_by_rr={}
        for rr in RR_LEVELS:
            paths={i:path_for(bars,i,case,rr) for i in (0,1)}
            a,r,b=replay([0,1],paths)
            si,aa,rrj,bb=independent_stream(bars,case,[0,1],rr)
            require(si==[0,1] and aa==[core(v) for v in a]
                    and rrj==[(v['signal_index'],v['reason']) for v in r]
                    and bb==[(v['signal_index'],v['blocking_signal_index']) for v in b],
                    'Independent synthetic RR replay failed')
            accepted_by_rr[rr]=[v['signal_index'] for v in a]
            require(abs(paths[0]['target']-(1.1+rr*(1.1-1.0989)))<1e-12,
                    'Target must use pre-cost reference risk')
        require(accepted_by_rr[2.25]==[0,1] and accepted_by_rr[2.75]==[0],
                'RR duration must change subsequent eligibility')
    require(len(PASS11_DEFINITIONS)==59 and sum(map(len,PASS11_PINS.values()))==472,
            'Archived Pass11 controls missing')
    require(len(PASS12_DEFINITIONS)==15 and sum(map(len,PASS12_PINS.values()))==120,
            'Archived Pass12 controls missing')
    for kind in ('PRIMARY','RECLAIM','COMBINED'):
        definitions=[d for d in DEFINITIONS if d['kind']==kind]
        geometry=lambda d:{k:v for k,v in d.items() if k not in ('id','rr')}
        require(all(geometry(d)==geometry(definitions[0]) for d in definitions),
                'Entry geometry must be invariant across RR')


def self_test():
    require(len(configs())==9 and len(CASES)==8,'Configuration count')
    require(tuple(map(len,periods()))==(31,262,714),'Period boundaries')
    def bar(t,o,h,l,c):
        p=dict(o=o,h=h,l=l,c=c)
        return {'t':t,'mid':dict(p),'bid':dict(p),'ask':dict(p),'first_h1':t,'h1_count':4}
    b=[bar(START,1.1,1.1006,1.099,1.1005),bar(START+H4,1.1006,1.11,1.09,1.1)]
    p=path_for(b,0,CASES[0]);require(p['outcome']=='DUAL_STOP' and abs(p['r']+1)<1e-12,'Dual stop-first')
    b[1]=bar(START+H4,1.098,1.11,1.09,1.1)
    require(path_for(b,0,CASES[0])['r']<-1,'Gap loss must exceed -1R')
    b[1]=bar(START+H4,1.1005,1.1006,1.1004,1.1005)
    require(path_for(b,0,CASES[-2])['outcome']=='OPEN','Open cutoff retention')
    b[1]['first_h1']+=3600
    require(path_for(b,0,CASES[-2])['reason']=='ENTRY_AGE_EXCEEDS_120S','Age rejection')
    b[1]['first_h1']-=3600;b[1]['ask']['o']=1.10061
    require(path_for(b,0,CASES[-2])['reason']=='ADVERSE_ENTRY_EXCEEDS_10_TICKS','Adverse rejection')
    p={0:{'signal_index':0,'reason':'','exit_index':2},1:{'signal_index':1,'reason':'','exit_index':3},2:{'signal_index':2,'reason':'','exit_index':None}}
    a,_,bl=replay([0,1,2],p);require([v['signal_index'] for v in a]==[0,2] and len(bl)==1,'P0 exit-candle handling')
    require(longest_zero([0,0,1,0,0,0])==3,'Zero-month drought')
    require(response('POST','/')[0]==405,'No writes allowed')
    require(len(DEFINITIONS)==9 and len(comparison_pairs())==27 and len(ANCHORS)==2,'Pass14 study count')
    rr_replay_self_test()
    confirmation_self_test()
    p15_self_test()
    return {'status':'PASS','scope':'Synthetic software checks only; no historical result'}


def p15_self_test():
    def attempt(sid,side,entry,index,exit_clock,exit_index,reason=''):
        return {'sid':sid,'pair':'EUR_USD','side':side,'tf':'H1','rr':2.25,'signal':stamp(START+index*900),
                'entry':stamp(START+entry*900),'exit':None if exit_clock is None else stamp(START+exit_clock*900),
                'signal_index':index,'exit_index':exit_index,'r':None if exit_clock is None else 1.,'reason':reason}
    # Earlier long displaces short; blocked short cannot reserve its isolated holding
    # interval. A later short that would previously have been p0-blocked recovers.
    rows=[attempt('H4','BUY',4,0,8,2),attempt('H1_SHORT','SELL',5,1,20,20),
          attempt('H1_SHORT','SELL',8,2,9,3),attempt('M15_LONG','BUY',8,3,10,5),
          attempt('M15_LONG','BUY',10,5,11,6)]
    accepted,audit=p15_joint_replay(rows);p15_joint_gate(rows,accepted,audit)
    require([r['decision'] for r in audit]==['ACCEPTED','BLOCKED_OPPOSITE','ACCEPTED','BLOCKED_OPPOSITE','ACCEPTED'],
            'P15 displacement/recovery and exit-before-entry pair release')
    rows=[attempt('A','BUY',1,0,3,2),attempt('A','BUY',2,1,5,4),attempt('A','BUY',3,2,4,3),
          attempt('B','BUY',3,2,4,3)]
    accepted,audit=p15_joint_replay(rows);p15_joint_gate(rows,accepted,audit)
    require([r['decision'] for r in audit]==['ACCEPTED','BLOCKED_P0','ACCEPTED','ACCEPTED'],'P15 own p0 exit candle and same-side overlap')
    rows=[attempt('A','BUY',1,0,None,None,'INVALID_ENTRY_STOP_TARGET'),attempt('B','SELL',1,0,4,3),
          attempt('C','BUY',2,1,3,2),attempt('D','SELL',4,3,None,None),attempt('E','BUY',5,4,6,5)]
    accepted,audit=p15_joint_replay(rows);p15_joint_gate(rows,accepted,audit)
    require([r['decision'] for r in audit]==['REJECTED_INVALID_ENTRY_STOP_TARGET','ACCEPTED','BLOCKED_OPPOSITE','ACCEPTED','BLOCKED_OPPOSITE'],
            'P15 invalid nonoccupation and unfinished occupation')
    rows=[attempt('Z_H4','BUY',2,0,3,2),attempt('A_H1','SELL',2,0,4,3)]
    accepted,audit=p15_joint_replay(rows)
    require(accepted[0]['sid']=='A_H1' and audit[1]['decision']=='BLOCKED_OPPOSITE','P15 lexical SID entry tie')
    def bar(t,o,h,l,c):
        price=dict(o=o,h=h,l=l,c=c)
        return dict(t=t,mid=dict(price),bid=dict(price),ask=dict(price),first_h1=t,h1_count=4)
    boundary=int(P15_CUTOFF//H4*H4)
    bars=[bar(boundary-H4,1.0995,1.1001,1.099,1.1000),bar(boundary,1.1000,1.1300,1.0980,1.1000)]
    for case in CASES:
        p=p15_cutoff_path(bars,0,case,2.25)
        require(p['exit_index'] is None and p['r'] is None and p['outcome']=='OPEN','P15 forming H4 may not realize later stop/target')
        confirmation_assert_fields(p,p15_confirmation_cutoff_path(bars,0,case,2.25),'P15 independent forming cutoff')
    # Legacy paths likewise cannot consume an unfinished candle, and a dual-touch
    # SELL tie retains its archived target-first convention.
    q=[(P15_CUTOFF-1800,1.1,1.1002,1.0998,1.1),(P15_CUTOFF-900,1.1,1.12,1.08,1.1)]
    require(p15_legacy_path(q,0,'TEST','SELL','H1',3.5,1.)['reason']=='ENTRY_AT_OR_AFTER_PORTFOLIO_CUTOFF','P15 legacy cutoff entry')
    q=[(START,1.1,1.101,1.099,1.1),(START+900,1.1,1.12,1.08,1.1)]
    p=p15_legacy_path(q,0,'TEST','SELL','M15',3.5,1.)
    require(p['r']>0,'P15 archived short dual-touch tie')
    engine=p15_legacy_engine()
    def book(sid,entry,exit,r,pair='EUR_USD'):
        return dict(sid=sid,pair=pair,side='BUY',tf='M15',rr=2.25,signal=stamp(START),entry=stamp(START+entry),
                    exit=None if exit is None else stamp(START+exit),r=r)
    sample=[book('A',900,1800,2.),book('B',1800,2700,-1.),book('EUR_JPY_M15_SHORT',1800,None,None,'EUR_JPY')]
    sim=engine['simulate_book'](sample,'SYNTHETIC');p15_accounting_gate(sim)
    require(sim['events'][1]['event']=='EXIT' and abs(sim['events'][2]['risk_cash']-1.02)<1e-12,'P15 realized sizing and exit-before-entry')
    require(abs(sim['events'][-1]['balance_after']-100.98)<1e-12 and sim['summary']['open_at_cutoff']==1,'P15 open position and allocated floor')
    require(abs(sim['open_positions'][0]['risk_cash']-.765)<1e-12,'P15 incumbent risk override')
    broken=dict(sim);broken['events']=[dict(e) for e in sim['events']];broken['events'][2]['risk_cash']+=.1
    try:p15_accounting_gate(broken)
    except ValueError:pass
    else:raise ValueError('Independent accounting failed to detect mutation')
    atr=p15_rma([(START+i*900,1.,2.,0.,1.) for i in range(15)])
    require(atr[12] is None and atr[13]==2. and atr[14]==2.,'P15 original ATR seed')
    require(P15_CUTOFF==epoch('2026-09-20T18:29:00Z') and CANDIDATE_RR==2.25,'P15 frozen endpoints/RR')
    return {'status':'PASS','scope':'Synthetic interaction, cutoff and independent cash checks'}


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--self-test',action='store_true');parser.add_argument('--run-once',action='store_true');parser.add_argument('--output-dir')
    args=parser.parse_args()
    if args.output_dir:OUTPUT=Path(args.output_dir)
    if args.self_test:print(json.dumps(self_test()));sys.exit(0)
    if args.run_once:
        run();print(json.dumps(snapshot()));sys.exit(0 if snapshot()['status']=='COMPLETE' else 1)
    if os.environ.get('EURUSD_H4_PASS15_AUTOSTART',os.environ.get('EURUSD_H4_PASS14_AUTOSTART',os.environ.get('EURUSD_H4_PASS13_AUTOSTART',os.environ.get('EURUSD_H4_PASS12_AUTOSTART',os.environ.get('EURUSD_H4_PASS11_AUTOSTART','true'))))).lower()!='false':start()
    ThreadingHTTPServer(('0.0.0.0',int(os.environ.get('PORT','8000'))),Handler).serve_forever()
